#!/usr/bin/env python3
"""Seal bounded peer-QA metadata without changing independently extracted values."""
from pathlib import Path
import hashlib,json
D=Path(__file__).resolve().parent;S=D.parent.parent;Q=D/'peer-qa';H=lambda b:hashlib.sha256(b).hexdigest()
def load(p):return json.loads(p.read_bytes())
def save(p,o):p.write_text(json.dumps(o,ensure_ascii=False,indent=2)+'\n')
def main():
 a=load(Q/'comparison.json');assert not a['unresolved_differences'];manifest=load(Q/'peer-snapshot-manifest.json');w=load(Q/'pre-peer-witness.json');pre={r['path']:r for r in w['files']}
 for rel in ['data/county-turnout.csv','data/turnout/native-order.csv','data/turnout/native-2024-candidate-positions.csv','data/turnout/historical-candidate-positions.json.gz']:
  assert H((S/rel).read_bytes())==pre[rel]['sha256'],rel
 meta=dict(peer_agent_id=manifest['peer_agent_id'],status='shared_original_fields_and_canonical_source_position_reconstruction_agree',comparison_path='peer-qa/comparison.json',comparison_sha256=H((Q/'comparison.json').read_bytes()),immutable_peer_snapshot_manifest='peer-qa/peer-snapshot-manifest.json',immutable_peer_snapshot_manifest_sha256=H((Q/'peer-snapshot-manifest.json').read_bytes()),pre_peer_owned_witness='peer-qa/pre-peer-witness.json',original_value_ledger_unchanged=True,field_checks=a['total_field_checks'],unresolved_source_value_differences=0,earlier_peer_literal_order_reordered_rank_count=len(a['earlier_peer_literal_order_reordered_ranks']),explicit_method_flag_differences=len(a['method_lexical_flag_differences']),additional_nonnumeric_owned_admin_headings=len(a['owned_additional_stats2020_admin_headings']),canonical_peer_artifact_status='Own independent reconstruction checked against frozen peer source-position bodies; peer later re-sort/reciprocal artifact is a separate witness when supplied.',coordinator_acceptance=False,current_geography_approved=False)
 contract=load(D/'priority-set.json');contract['status']='independent_original_peer_source_fields_reconciled_coordinator_acceptance_pending';contract['peer_agreement']=meta;contract['source_object_paths']['peer_comparison']='peer-qa/comparison.json';contract['source_object_paths']['peer_source_position_map']='peer-qa/source-position-map.json.gz';contract['source_object_paths']['peer_snapshot_manifest']='peer-qa/peer-snapshot-manifest.json';save(D/'priority-set.json',contract)
 control=load(D/'independent-control-check.json');control['peer_agreement_status']='Actual independent peer original fields and canonical order/maps reconciled; see peer-qa/comparison.json. This preflight comparison remains supplementary.';control['peer_agreement']=meta;save(D/'independent-control-check.json',control)
 report=(S/'turnout.md').read_text().replace('508,514',format(a['total_field_checks'],','))
 report=report.replace('**Peer agreement and coordinator acceptance are pending; current geometry is not approved.**','**The actual independent peer’s shared source fields and canonical source-position order/maps reconcile. Coordinator acceptance remains pending; current geometry is not approved.**')
 report=report.replace('it is **not independent research-peer agreement**.','it remains supplementary to the [actual independent research-peer comparison](data/turnout/peer-qa/comparison.json).')
 report=report.replace('The actual peer has not launched at this snapshot, so shared-field/full-order agreement and coordinator acceptance remain outstanding.','The actual independent peer `0eb74f9e-f473-403c-adee-715808064b55` has now supplied originals-first stable artifacts. The bounded comparison below verifies shared original fields and the complete canonical order/maps; coordinator acceptance remains outstanding.')
 section='''\n## Bounded independent peer reconciliation\n\nThe [pre-peer owned-byte witness](data/turnout/peer-qa/pre-peer-witness.json) retains exact dated report/contract/data/script bodies before any peer-sealing changes. [The immutable peer snapshot](data/turnout/peer-qa/peer-snapshot-manifest.json) pins the actual independent peer’s originals-first summary, candidate positions, native units, controls, statistics, original references and earlier native order read-only. No peer votes replace this turnout extraction. [Reproducible comparison](data/turnout/compare_peer.py) passes **508,514 field checks**, with no unresolved source-value difference: all36,565 peer candidate/control positions,4,931 native contest contexts,2,099 peer statistical row objects, raw cells/types/styles/raw values/formulas, exact candidate/party headers,8/42 historical candidate nulls, all44 county controls, native/footer/state/appendix values, and ballot/registration fields. Independently acquired2022 public HTML bodies differ in dynamic bytes but every literal published table header/value agrees. The seven Boundary residuals and Bingham zero statistics-only row agree unchanged. [Full comparison and exceptions](data/turnout/peer-qa/comparison.json).\n\nThe one-to-one [source-position map](data/turnout/peer-qa/source-position-map.json.gz) uses the same original SHA256/member/worksheet/row range and literal county/Precinct label. It changes no native ID and asserts no cross-year/current geographic equivalence. The peer’s earlier order sorted tied votes by literal county/label/source-row. The canonical contract retains **descending eleven-candidate votes, then lexical complete source-position key**. Re-sorting the peer’s own independently extracted values under that explicit key reproduces every985 rank, cumulative total and all44 ordered full/priority/remainder child maps;528 membership and the unique Osburn crossing never changed. Exactly six tied pairs reorder twelve ranks:\n\n| Ranks | Equal votes | Canonical earlier entry → later entry | Earlier peer presentation |\n| --- | --- | --- | --- |\n|171–172|1,378|Ada1501(row1224) →1415(row262)|Reverse|\n|252–253|1,267|Ada2219(row1029) →2019(row522)|Reverse|\n|286–287|1,216|Ada2305(row1120) →2103(row574)|Reverse|\n|459–460|896|Bonneville49(row4942) →07(row5085)|Reverse|\n|518–519|785|JeffersonMENAN(row8413) →LEWISVILLE(row8465)|Reverse|\n|974–975|37|Lewis007Mohler(row10207) →006Reubens(row10272)|Reverse|\n\nOther representational differences remain explicit. Historical peer county parents use the workbook’s short county name; turnout uses the Census county/FIPS parent while retaining the same raw heading/cell. Candidate `F:<offset>` or column keys are local source locators, not globally interchangeable candidate IDs. Turnout flags the literal abbreviation ABS as a search aid at2024 row12547 and2022 Senate rows1124/1125 and governor rows1126/1127; the peer leaves these five flags unspecified. Both preserve the identical literal labels and neither treats lexical flags as an operational method partition. Turnout separately inventories statistics appendix headings2020 row1147 `Statewide` and1151 `Ada County`; the peer does not make separate statistical objects for these all-four-null headings, but retains their identical pinned original bytes. They are not extra precincts or Washington votes. The peer’s separate2020 county-workbook statewide statistics record also carries literal county=`TOTAL`, role=`state_control`; this is an administrative control label, never a45th county or Washington child. These are documented presentation/coverage differences, not normalized-away source discrepancies.\n\nThe existing Twin Falls LD24 sample claim remains based only on its pinned original primary PDF and viewed first page. No peer-derived roster, current choice IDs, geometry approval or statewide/later eligible-write-in exhaustion is imported. Peer source-field reconciliation is complete at the pinned extraction snapshot; any subsequent peer calculator/report is a distinct artifact. **No coordinator acceptance is claimed.**\n'''
 section=section.replace('508,514',format(a['total_field_checks'],','))
 if '\n## Bounded independent peer reconciliation\n'not in report:report+=section
 if 'literal county=`TOTAL`'not in report:report=report.replace('These are documented presentation/coverage differences, not normalized-away source discrepancies.','The peer’s separate2020 county-workbook statewide statistics record also carries literal county=`TOTAL`, role=`state_control`; this is an administrative control label, never a45th county or Washington child. These are documented presentation/coverage differences, not normalized-away source discrepancies.')
 (S/'turnout.md').write_text(report)
 schema=D/'source/SCHEMA.md';s=schema.read_text();s=s.replace('Actual research-peer agreement and coordinator acceptance remain pending until independently launched peer artifacts are available.','The actual independently launched peer’s shared raw fields and canonical source-position reconstruction are now checked by `compare_peer.py`; exact peer bodies and pre-peer own bodies remain in `peer-qa/`. The earlier peer literal-label tie order differs at twelve tied ranks and is retained explicitly. See `peer-qa/comparison.json`; coordinator acceptance remains pending.')
 s+='\nFor the bounded peer seal, run `compare_peer.py`, then `seal_peer.py` after the original build/report steps and before `validate.py`/`asset_manifest.py`/`--verify-assets`. The comparator only reads immutable peer snapshots and retained originals. `seal_peer.py` checks unchanged original data hashes against the pre-peer witness and updates report/contract QA metadata, never original values or the canonical order.\n'if 'For the bounded peer seal'not in s else''
 schema.write_text(s)
 print('Peer metadata/report sealed; original counts/order unchanged; coordinator acceptance pending.')
if __name__=='__main__':main()
